-- =============================================================================
-- 508 — LE CAHIER D'EXERCICES DE 2DE (partie 10)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/2de/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 508 --niveau 2de --fichiers maths.n2,musique.n1,physique-chimie.n1 --suffixe 10 > supabase/contenu/508_exercices_2de_10.sql
--
-- 75 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   maths.n2                30 exercices · 10 chapitres
--   musique.n1               9 exercices · 3 chapitres
--   physique-chimie.n1      36 exercices · 12 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('5731af00-4e7e-53c3-a955-cf8dc2e069c7'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La température d’une journée d’avril à Annecy","competence":"lire-graphique","situation":"Un capteur installé sur le port d’Annecy relève la température toutes les trois heures. Sa fonction T associe à chaque heure h (de 0 à 24) la température en °C. Le graphique de Lina en garde la trace.","documents":[{"id":"temp","type":"graphique","forme":"courbe","titre":"Température T(h) relevée au port","categories":["0","3","6","9","12","15","18","21","24"],"series":[{"nom":"Température","valeurs":[4,2,2,6,10,14,12,8,6],"teinte":"corail"}],"axeY":{"titre":"Température","unite":"°C","min":0,"max":16,"pas":2},"axeX":{"titre":"Heure h"},"source":"Relevés imaginés pour l’exercice"}],"questions":[{"enonce":"Touche le point qui donne la température à 12 h.","aide":"Cherche l’abscisse 12 sur l’axe horizontal, puis le point au-dessus.","type":"zone","document":"temp","multiple":false},{"enonce":"Quelle est l’image de 21 par la fonction T ?","aide":"L’image de 21, c’est la température relevée à 21 h.","type":"nombre","unite":"°C"},{"enonce":"À quelles heures la température vaut-elle 2 °C ? Touche les deux points correspondants.","aide":"Trace mentalement l’horizontale d’ordonnée 2 et regarde tous les points qu’elle rencontre.","type":"zone","document":"temp","multiple":true},{"enonce":"À quelle heure la température est-elle la plus élevée ?","aide":"Cherche le point le plus haut de la courbe, puis lis son abscisse.","type":"nombre","unite":"h"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"À h = 12, le point de la courbe est à l’ordonnée 10 : **T(12) = 10 °C**. On part de l’heure (abscisse) pour lire la température (ordonnée)."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 °C","explication":"On repère 21 sur l’axe horizontal et on lit l’ordonnée du point : l’image de 21 est **8** (T(21) = 8 °C)."},{"cle":{"type":"zone","ids":["k1","k2"]},"explication":"Les points d’ordonnée 2 sont ceux de **3 h et 6 h**. Un nombre peut avoir plusieurs antécédents : ici 3 et 6 sont deux antécédents de 2."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 h","explication":"Le point le plus haut a pour ordonnée 14 : le maximum de T est atteint en **h = 15**, soit à 15 h."}]$ex$::jsonb),
  ('5731af00-4e7e-53c3-a955-cf8dc2e069c7'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un enclos pour les poules de Léa","competence":"resoudre","situation":"Léa dispose de 20 m de grillage pour fermer un enclos rectangulaire. Si la largeur est x (en m), la longueur est 10 − x et l’aire vaut A(x) = x(10 − x). Elle a commencé un tableau de valeurs pour choisir la largeur.","documents":[{"id":"tab","type":"tableau","titre":"Aire de l’enclos selon sa largeur","colonnes":["Largeur x (m)","Aire A(x) (m²)"],"lignes":[[1,9],[2,16],[3,21],[4,24],[5,25],[6,24],[7,21],[8,"?"],[9,9]],"enteteLignes":true,"source":"Valeurs calculées avec A(x) = x(10 − x)"}],"questions":[{"enonce":"Calcule la case manquante : quelle est l’aire A(8) ?","aide":"Remplace x par 8 dans A(x) = x(10 − x).","type":"nombre","unite":"m²"},{"enonce":"Touche les deux cases du tableau où l’aire vaut 21 m².","aide":"Parcours la colonne des aires : le nombre 21 y apparaît deux fois.","type":"zone","document":"tab","multiple":true},{"enonce":"Quelle est la plus grande aire du tableau ?","aide":"Compare toutes les valeurs de la colonne des aires.","type":"nombre","unite":"m²"},{"enonce":"Que peut-on dire de la fonction A sur l’intervalle [1 ; 9] ?","aide":"Lis la colonne des aires de haut en bas : monte-t-elle toujours ?","type":"choix","options":[{"id":"a","texte":"Elle croît jusqu’à x = 5 puis décroît"},{"id":"b","texte":"Elle croît sur tout l’intervalle"},{"id":"c","texte":"Elle décroît sur tout l’intervalle"},{"id":"d","texte":"Elle est constante sur l’intervalle"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":16,"tolerance":0},"affichage":"16 m²","explication":"A(8) = 8 × (10 − 8) = 8 × 2 = **16** m². On remplace x par 8, on calcule l’image."},{"cle":{"type":"zone","ids":["r2c1","r6c1"]},"explication":"L’aire vaut 21 m² pour une largeur de **3 m** et pour une largeur de **7 m** : 21 a deux antécédents, 3 et 7."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 m²","explication":"En parcourant la colonne, la valeur maximale est **25 m²**, atteinte pour x = 5 (un carré de 5 m de côté)."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les aires passent de 9 à 25 puis redescendent à 9 : A est **croissante sur [1 ; 5] puis décroissante sur [5 ; 9]**. On donne toujours les variations intervalle par intervalle."}]$ex$::jsonb),
  ('5731af00-4e7e-53c3-a955-cf8dc2e069c7'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le profil du parcours de trottinette","competence":"lire-graphique","situation":"Un parc dessine un parcours de trottinette dont l’altitude f(x) (en m, par rapport à la rue) dépend de la distance x (en dizaines de mètres). Le service technique a tracé la courbe de f et préparé un tableau de signes, mais une case est fausse.","documents":[{"id":"profil","type":"graphique","forme":"courbe","titre":"Altitude f(x) du parcours","categories":["−2","−1","0","1","2","3","4"],"series":[{"nom":"Altitude","valeurs":[-5,0,3,4,3,0,-5],"teinte":"violet"}],"axeY":{"titre":"Altitude","unite":"m","min":-6,"max":6,"pas":2},"axeX":{"titre":"x (dizaines de m)"},"source":"Profil imaginé pour l’exercice"},{"id":"signes","type":"tableau","titre":"Le tableau de signes proposé","colonnes":["x","−2 ≤ x < −1","−1 < x < 3","3 < x ≤ 4"],"lignes":[["Signe de f(x)","−","+","+"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux points où le parcours est exactement à l’altitude de la rue (f(x) = 0).","aide":"Résoudre f(x) = 0, c’est chercher les points de la courbe situés sur l’axe horizontal.","type":"zone","document":"profil","multiple":true},{"enonce":"Quelle est l’altitude maximale du parcours ?","aide":"Cherche le point le plus haut de la courbe.","type":"nombre","unite":"m"},{"enonce":"Touche la case du tableau de signes qui contredit la courbe.","aide":"Pour 3 < x ≤ 4, regarde de quel côté de l’axe horizontal la courbe se trouve.","type":"zone","document":"signes","multiple":false},{"enonce":"Sur quel intervalle la fonction f est-elle croissante ?","aide":"Une fonction croissante a une courbe qui monte quand on avance vers la droite.","type":"choix","options":[{"id":"a","texte":"De −2 à 1"},{"id":"b","texte":"De 1 à 4"},{"id":"c","texte":"De −2 à 4"},{"id":"d","texte":"De −1 à 3"}],"multiple":false},{"enonce":"Combien de nombres entiers x de l’intervalle [−2 ; 4] vérifient f(x) ≥ 0 ?","aide":"Compte les points de la courbe situés sur l’axe ou au-dessus (f(x) = 0 compte aussi).","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k1","k3"]},"explication":"La courbe coupe l’axe des abscisses en **x = −1 et x = 3** : ce sont les solutions de f(x) = 0. On lit des abscisses, pas des ordonnées."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 m","explication":"Le point le plus haut a pour ordonnée 4 : le **maximum de f vaut 4**, atteint en x = 1."},{"cle":{"type":"zone","ids":["r0c3"]},"explication":"Entre 3 et 4, la courbe passe **sous** l’axe des abscisses : f(x) est négative, et non positive comme l’indique la dernière case. Le signe se lit sur la position de la courbe par rapport à l’axe."},{"cle":{"type":"choix","ids":["a"]},"explication":"La courbe monte de x = −2 jusqu’à son maximum en x = 1, puis redescend : f est **croissante sur [−2 ; 1]**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5","explication":"Les entiers −1, 0, 1, 2 et 3 donnent une altitude positive ou nulle : il y en a **5**. Les points d’abscisse −2 et 4 sont sous l’axe."}]$ex$::jsonb),
  ('4ed95570-6c2d-5152-b81e-57fdaaaa08c8'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"L’abonnement du club d’escalade","competence":"calculer","situation":"Maëlle veut s’inscrire à un club d’escalade. Elle lit l’affiche des tarifs : le coût de x séances dans le mois est donné par une fonction f.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Club Grimp’Alpes","sousTitre":"Tarifs du mois","emoji":"🧗","lignes":[{"texte":"Inscription mensuelle (payée une seule fois)","valeur":"12 €","id":"z1"},{"separateur":true},{"texte":"Entrée pour chaque séance","valeur":"3 €","id":"z2"}],"pied":"Tarifs imaginés pour l’exercice","teinte":"violet"}],"questions":[{"enonce":"Touche la ligne qui donne la somme à payer en plus à chaque nouvelle séance.","aide":"Cherche le tarif qui se répète à chaque séance, pas celui payé une seule fois.","type":"zone","document":"affiche","multiple":false},{"enonce":"Combien Maëlle paie-t-elle pour 5 séances dans le mois ?","aide":"Ajoute l’inscription au prix de 5 séances.","type":"nombre","unite":"€"},{"enonce":"Complète l’écriture de la fonction qui donne le coût de x séances.","aide":"Dans ax + b, a est le prix qui se répète et b le prix payé une seule fois.","type":"trous","segments":["La fonction est f(x) = ",0," x + ",1,"."],"banque":["3","36","12","15"]},{"enonce":"Maëlle a 45 € à dépenser dans le mois. Combien de séances peut-elle suivre au maximum ?","aide":"Résous 3x + 12 = 45.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Les **3 €** de chaque séance sont le coefficient directeur a ; les 12 € d’inscription sont payés une fois, c’est l’ordonnée à l’origine b."},{"cle":{"type":"nombre","valeur":27,"tolerance":0},"affichage":"27 €","explication":"f(5) = 3 × 5 + 12 = 15 + 12 = **27 €**."},{"cle":{"type":"trous","trous":[["3"],["12"]]},"affichage":"3 · 12","explication":"On a **f(x) = 3x + 12** : 3 € par séance (a) et 12 € de forfait fixe (b). C’est une fonction affine."},{"cle":{"type":"nombre","valeur":11,"tolerance":0},"affichage":"11","explication":"3x + 12 = 45 donne 3x = 33, donc x = **11** séances : f(11) = 33 + 12 = 45 €."}]$ex$::jsonb),
  ('4ed95570-6c2d-5152-b81e-57fdaaaa08c8'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Tarif plein ou carte Ciné+ ?","competence":"lire-graphique","situation":"Le cinéma de Cléa propose deux formules : payer chaque séance au tarif plein, ou acheter une carte Ciné+ puis payer chaque séance moins cher. Le graphique compare le coût total (en €) selon le nombre x de séances.","documents":[{"id":"tarifs","type":"graphique","forme":"courbe","titre":"Coût selon le nombre de séances","categories":["0","1","2","3","4","5","6","7","8"],"series":[{"nom":"Tarif plein","valeurs":[0,8,16,24,32,40,48,56,64],"teinte":"corail"},{"nom":"Carte Ciné+","valeurs":[16,20,24,28,32,36,40,44,48],"teinte":"violet"}],"axeY":{"titre":"Coût","unite":"€","min":0,"max":64,"pas":8},"axeX":{"titre":"Nombre de séances x"},"source":"Tarifs imaginés pour l’exercice"}],"questions":[{"enonce":"Touche le point du tarif plein qui correspond à 6 séances.","aide":"Repère 6 sur l’axe horizontal, puis le point de la courbe qui monte le plus vite.","type":"zone","document":"tarifs","multiple":false},{"enonce":"Combien coûtent 6 séances avec la carte Ciné+ ?","aide":"Lis l’ordonnée du point de la courbe violette d’abscisse 6.","type":"nombre","unite":"€"},{"enonce":"De combien d’euros le coût avec la carte augmente-t-il à chaque séance supplémentaire ?","aide":"Calcule la différence entre deux points consécutifs de la courbe violette.","type":"nombre","unite":"€"},{"enonce":"Résous 8x = 4x + 16 : pour quel nombre de séances les deux formules coûtent-elles le même prix ?","aide":"Regroupe les x du même côté : 8x − 4x = 16.","type":"nombre"},{"enonce":"Cléa ira 7 fois au cinéma cette année. Que lui conseilles-tu ?","aide":"Au-delà de 4 séances, quelle courbe est la plus basse ?","type":"choix","options":[{"id":"a","texte":"On ne peut pas savoir"},{"id":"b","texte":"Le tarif plein : 44 € au lieu de 56 €"},{"id":"c","texte":"La carte : 44 € au lieu de 56 €"},{"id":"d","texte":"Les deux formules coûtent pareil"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k6"]},"explication":"Pour 6 séances au tarif plein, on lit **48 €**. Le tarif plein est la droite la plus pentue : 8 € par séance."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 €","explication":"Pour x = 6, la courbe de la carte est à l’ordonnée **40 €**."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 €","explication":"Le coût passe de 16 € à 20 € puis 24 € : il augmente de **4 € par séance**. C’est le coefficient directeur a = 4 de f(x) = 4x + 16."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"8x = 4x + 16 donne 4x = 16, donc x = **4** séances : c’est l’abscisse du point où les deux courbes se croisent."},{"cle":{"type":"choix","ids":["c"]},"explication":"Pour x = 7 : carte 4 × 7 + 16 = 44 €, tarif plein 8 × 7 = 56 €. **La carte** est plus avantageuse dès que x dépasse 4."}]$ex$::jsonb),
  ('4ed95570-6c2d-5152-b81e-57fdaaaa08c8'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La grille tarifaire du taxi de Samir","competence":"modeliser","situation":"Samir, chauffeur de taxi, a oublié sa grille tarifaire. Il sait que le prix d’une course est une fonction affine de la distance, et il a gardé deux de ses factures. Son neveu en a tiré un petit programme Python.","documents":[{"id":"factures","type":"tableau","titre":"Deux courses relevées","colonnes":["Course","Distance x (km)","Prix f(x) (€)"],"lignes":[["Course A",4,11],["Course B",10,20]],"enteteLignes":true,"source":"Factures imaginées pour l’exercice"},{"id":"prog","type":"texte","genre":"consigne","titre":"Le programme du neveu","auteur":"Programme écrit pour l’exercice","blocs":["def prix(km):","    return 5 + 1.5 * km","print(prix(12))"]}],"questions":[{"enonce":"Remets dans l’ordre la méthode pour déterminer une fonction affine à partir de deux points.","aide":"On ne peut pas trouver b avant d’avoir a.","type":"ordre","items":[{"id":"a","texte":"Écrire f(x) = ax + b"},{"id":"b","texte":"Calculer a avec le taux d’accroissement entre les deux points"},{"id":"c","texte":"Contrôler avec l’autre point"},{"id":"d","texte":"Remplacer x et f(x) d’un des points pour trouver b"}]},{"enonce":"Calcule le coefficient directeur a de la fonction affine (en € par km).","aide":"Divise l’écart des prix par l’écart des distances.","type":"nombre"},{"enonce":"Quelle est l’ordonnée à l’origine b, c’est-à-dire le prix de la prise en charge (en €) ?","aide":"Utilise f(4) = 1,5 × 4 + b = 11.","type":"nombre"},{"enonce":"Qu’affiche ce programme ? (Écris la valeur affichée.)","aide":"Calcule prix(12) = 5 + 1,5 × 12.","type":"nombre"},{"enonce":"Un client a payé 35 € : quelle distance (en km) a-t-il parcourue ?","aide":"Résous 1,5x + 5 = 35.","type":"nombre","unite":"km"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"ordre","ids":["b","d","a","c"]},"explication":"On calcule d’abord **a**, puis **b** avec un point, on écrit **f(x) = ax + b**, et on **contrôle** avec le second point."},{"cle":{"type":"nombre","valeur":1.5,"tolerance":0},"affichage":"1,5","explication":"a = (20 − 11) ÷ (10 − 4) = 9 ÷ 6 = **1,5** : chaque kilomètre coûte 1,50 €."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5","explication":"1,5 × 4 + b = 11 donne 6 + b = 11, donc b = **5** €. Contrôle : 1,5 × 10 + 5 = 20 ✓."},{"cle":{"type":"nombre","valeur":23,"tolerance":0},"affichage":"23","explication":"prix(12) = 5 + 1,5 × 12 = 5 + 18 = **23**. Python affiche 23.0 : c’est le prix en euros d’une course de 12 km."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 km","explication":"1,5x + 5 = 35 donne 1,5x = 30, donc x = **20** km."}]$ex$::jsonb),
