   $ex$[{"cle":{"type":"nombre","valeur":16,"tolerance":0},"affichage":"16 m²","explication":"4² = 4 × 4 = **16** m². C’est la case qui manquait."},{"cle":{"type":"zone","ids":["r0c3"]},"explication":"Pour c = 3, l’aire est **9 m²** : 3² = 9."},{"cle":{"type":"nombre","valeur":2.25,"tolerance":0},"affichage":"2,25 m²","explication":"1,5² = 1,5 × 1,5 = **2,25** m². Le tableau ne donne que des côtés entiers, mais la formule marche pour tout nombre."},{"cle":{"type":"choix","ids":["a"]},"explication":"On passe de 4 m² à 16 m² : l’aire est **multipliée par 4**. La fonction carré n’est pas proportionnelle."}]$ex$::jsonb),
