  ('edc04d10-a2b2-5bd7-8771-91d651f4a52b'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Mille mètres à vélo, à toutes les vitesses","competence":"modeliser","situation":"Théo teste son vélo sur un tronçon de 1 km. S’il roule à la vitesse v (en km/h), il met t(v) = 1/v heure. Il note ses essais dans un tableau, mais l’un d’eux est resté vide.","documents":[{"id":"essais","type":"tableau","titre":"Durée du tronçon selon la vitesse","colonnes":["Vitesse v (km/h)","4","5","10","20","25"],"lignes":[["Durée t(v) = 1/v (h)",0.25,0.2,0.1,0.05,"?"]],"enteteLignes":true,"source":"Essais imaginés pour l’exercice"}],"questions":[{"enonce":"Touche la durée du tronçon quand Théo roule à 10 km/h.","aide":"Repère la colonne de la vitesse 10.","type":"zone","document":"essais","multiple":false},{"enonce":"Complète la case vide : quelle est la durée t(25) en heures ?","aide":"Calcule 1 ÷ 25.","type":"nombre","unite":"h"},{"enonce":"À 20 km/h, combien de minutes dure le tronçon ?","aide":"La durée est 0,05 h ; une heure vaut 60 minutes.","type":"nombre","unite":"min"},{"enonce":"À quelle vitesse (en km/h) Théo met-il une demi-heure (0,5 h) ?","aide":"Résous 1/v = 0,5.","type":"nombre","unite":"km/h"},{"enonce":"Quand la vitesse double (de 10 à 20 km/h), que devient la durée ?","aide":"Compare les durées dans les colonnes 10 et 20.","type":"choix","options":[{"id":"a","texte":"Elle est multipliée par 2"},{"id":"b","texte":"Elle est divisée par 2"},{"id":"c","texte":"Elle ne change pas"},{"id":"d","texte":"Elle est divisée par 4"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c3"]},"explication":"À 10 km/h, le tronçon dure **0,1 h**, c’est-à-dire 6 minutes."},{"cle":{"type":"nombre","valeur":0.04,"tolerance":0},"affichage":"0,04 h","explication":"t(25) = 1/25 = **0,04** h."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 min","explication":"0,05 h × 60 = **3 minutes**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 km/h","explication":"1/v = 0,5 donne v = 1 ÷ 0,5 = **2** km/h : c’est la marche très lente."},{"cle":{"type":"choix","ids":["b"]},"explication":"La durée passe de 0,1 h à 0,05 h : elle est **divisée par 2**. Les grandeurs inversement proportionnelles suivent la fonction inverse."}]$ex$::jsonb),
  ('edc04d10-a2b2-5bd7-8771-91d651f4a52b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"L’inéquation 1/x ≥ 3 de Maya","competence":"raisonner","situation":"Maya veut résoudre l’inéquation 1/x ≥ 3. Elle sait qu’il ne faut pas multiplier par x sans connaître son signe : elle passe tout d’un même côté et étudie le signe de (1 − 3x)/x. Elle teste aussi quelques valeurs.","documents":[{"id":"signes","type":"tableau","titre":"Le tableau de signes de Maya (a est la valeur qui annule 1 − 3x)","colonnes":["x","x < 0","0 < x < a","x > a"],"lignes":[["Signe de 1 − 3x","+","+","−"],["Signe de x","−","+","+"],["Signe de (1 − 3x)/x","−","+","−"]],"enteteLignes":true},{"id":"essais","type":"tableau","titre":"Ses essais","colonnes":["Valeur de x","0,2","0,25","0,5","1"],"lignes":[["1/x",5,4,2,1]],"enteteLignes":true}],"questions":[{"enonce":"Quelle est la valeur interdite de l’inéquation 1/x ≥ 3 ?","aide":"Quelle valeur de x ne permet pas de calculer 1/x ?","type":"nombre"},{"enonce":"Quelle est la valeur a qui annule 1 − 3x ? (Écris une fraction ou une valeur approchée à 0,01 près.)","aide":"Résous 1 − 3x = 0.","type":"nombre"},{"enonce":"Touche les essais pour lesquels 1/x ≥ 3 est vrai.","aide":"Cherche dans la ligne 1/x les valeurs supérieures ou égales à 3.","type":"zone","document":"essais","multiple":true},{"enonce":"Complète la solution de l’inéquation 1/x ≥ 3.","aide":"Dans le tableau, le quotient est positif ou nul seulement entre 0 et a.","type":"trous","segments":["Les solutions sont les nombres x tels que 0 < x ≤ ",0,"."],"banque":["1","3","0","1/3"]},{"enonce":"Combien de nombres entiers sont solutions de 1/x ≥ 3 ?","aide":"Cherche un entier dans l’intervalle ]0 ; 1/3].","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0,"tolerance":0},"affichage":"0","explication":"On ne peut pas diviser par zéro : **0 est la valeur interdite**, et elle sera toujours exclue de l’ensemble des solutions."},{"cle":{"type":"nombre","valeur":0.3333333333333333,"tolerance":0.006},"affichage":"0,3333","explication":"1 − 3x = 0 donne x = **1/3** ≈ 0,33. C’est la valeur où le numérateur change de signe."},{"cle":{"type":"zone","ids":["r0c1","r0c2"]},"explication":"Pour x = 0,2 et x = 0,25, on trouve **5 et 4**, qui sont supérieurs à 3. Pour x = 0,5 et x = 1, on trouve 2 et 1 : trop petits."},{"cle":{"type":"trous","trous":[["1 3"]]},"affichage":"1/3","explication":"Le quotient (1 − 3x)/x est positif sur ]0 ; 1/3] (nul en 1/3, le crochet est fermé) : **S = ]0 ; 1/3]**. Le crochet est ouvert en 0, valeur interdite."},{"cle":{"type":"nombre","valeur":0,"tolerance":0},"affichage":"0","explication":"Aucun entier ne se trouve entre 0 (exclu) et 1/3 : il y en a **0**. Le nombre 1, par exemple, donne 1/1 = 1, qui est plus petit que 3."}]$ex$::jsonb),
  ('4a031ed0-b4ad-598f-8555-fd3e7ddc6ae1'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les baskets en solde","competence":"calculer","situation":"Yanis veut acheter une paire de baskets. En magasin, une affichette annonce une remise de 25 % sur le prix de départ.","documents":[{"id":"etiquette","type":"fiche","modele":"etiquette","entete":"Baskets de running","sousTitre":"Soldes du week-end","emoji":"👟","lignes":[{"texte":"Prix de départ","valeur":"80 €","id":"z1"},{"separateur":true},{"texte":"Remise","valeur":"− 25 %","id":"z2"}],"pied":"Étiquette imaginée pour l’exercice","teinte":"corail"}],"questions":[{"enonce":"Touche la ligne qui indique le taux de la remise.","aide":"Cherche la ligne où figure un pourcentage.","type":"zone","document":"etiquette","multiple":false},{"enonce":"De combien d’euros les baskets sont-elles réduites ?","aide":"Calcule 25 % de 80 : multiplie 80 par 25/100.","type":"nombre","unite":"€"},{"enonce":"Quel est le prix soldé des baskets ?","aide":"Enlève la remise au prix de départ.","type":"nombre","unite":"€"},{"enonce":"Par quel coefficient multiplie-t-on un prix pour appliquer une baisse de 25 % ?","aide":"Une baisse de t % se traduit par 1 − t/100.","type":"choix","options":[{"id":"a","texte":"0,025"},{"id":"b","texte":"0,25"},{"id":"c","texte":"0,75"},{"id":"d","texte":"1,25"}],"multiple":false}]}$ex$::jsonb,
