  ('4a031ed0-b4ad-598f-8555-fd3e7ddc6ae1'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Deux hausses successives pour Flixo","competence":"modeliser","situation":"Le service de vidéo en ligne Flixo coûtait 12 € par mois en janvier. En mars, son prix augmente de 10 %, puis en septembre de 25 % par rapport au prix de mars.","documents":[{"id":"prix","type":"tableau","titre":"Les prix de l’abonnement","colonnes":["Date","Évolution","Prix mensuel (€)"],"lignes":[["Janvier","—",12],["Mars","+ 10 %","?"],["Septembre","+ 25 %","?"]],"enteteLignes":true,"source":"Prix imaginés pour l’exercice"}],"questions":[{"enonce":"Quel est le prix mensuel après la hausse de mars ?","aide":"Multiplie 12 par le coefficient 1,10.","type":"nombre","unite":"€"},{"enonce":"Quel est le prix mensuel après la hausse de septembre ?","aide":"La hausse de 25 % s’applique au prix de mars, pas à celui de janvier.","type":"nombre","unite":"€"},{"enonce":"Quelle est la hausse globale, en pourcentage, entre janvier et septembre ?","aide":"Multiplie les deux coefficients 1,10 et 1,25, puis retire 1.","type":"nombre","unite":"%"},{"enonce":"Marie affirme : « 10 % puis 25 %, cela fait 35 % de hausse. » Que lui répondre ?","aide":"Compare 35 % de 12 € avec la vraie hausse de janvier à septembre.","type":"choix","options":[{"id":"a","texte":"Vrai : il suffit de faire la moyenne de 10 % et 25 %"},{"id":"b","texte":"Faux : la hausse totale est de 25 % − 10 % = 15 %"},{"id":"c","texte":"Vrai : les pourcentages d’évolutions successives s’additionnent"},{"id":"d","texte":"Faux : on multiplie les coefficients 1,10 × 1,25 : la hausse est de 37,5 %"}],"multiple":false},{"enonce":"Quelle baisse (en %, arrondie au dixième) ramènerait le prix de septembre au prix de janvier ?","aide":"L’évolution réciproque a pour coefficient l’inverse de 1,375.","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":13.2,"tolerance":0},"affichage":"13,2 €","explication":"12 × 1,10 = **13,20 €**. Le coefficient d’une hausse de 10 % est 1 + 10/100 = 1,10."},{"cle":{"type":"nombre","valeur":16.5,"tolerance":0},"affichage":"16,5 €","explication":"13,20 × 1,25 = **16,50 €**."},{"cle":{"type":"nombre","valeur":37.5,"tolerance":0},"affichage":"37,5 %","explication":"1,10 × 1,25 = 1,375, donc une hausse de **37,5 %**. On vérifie : 16,50 ÷ 12 = 1,375."},{"cle":{"type":"choix","ids":["d"]},"explication":"35 % de 12 € donneraient 16,20 € alors que le prix réel est 16,50 €. Pour des évolutions successives, on **multiplie les coefficients**, on n’additionne jamais les pourcentages."},{"cle":{"type":"nombre","valeur":27.3,"tolerance":0.1},"affichage":"27,3 %","explication":"1 ÷ 1,375 ≈ 0,7273, donc une baisse d’environ **27,3 %** — et non de 37,5 %, car la baisse s’applique à un prix plus élevé."}]$ex$::jsonb),
