  ('d6f0ce64-ca85-5f51-9cd2-7fecd9d86b4b'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Salaire moyen ou salaire médian dans une PME ?","competence":"argumenter","situation":"Dans une petite entreprise de huit personnes, la dirigeante annonce : « Le salaire moyen est de 2 625 € ! » Un délégué du personnel trouve que ce chiffre ne reflète pas ce que gagnent les employés. Voici les salaires nets mensuels.","documents":[{"id":"salaires","type":"graphique","forme":"barres","titre":"Salaires nets mensuels dans l’entreprise","categories":["Ana","Ben","Clo","Dan","Eli","Fab","Gus","Dir."],"series":[{"nom":"Salaire (€)","valeurs":[1500,1550,1600,1650,1700,1750,1800,9450],"teinte":"turquoise"}],"axeY":{"titre":"Salaire net","unite":"€","min":0,"max":10000,"pas":2000},"valeurs":true,"source":"Salaires imaginés pour l’exercice"}],"questions":[{"enonce":"Touche la barre qui tire la moyenne vers le haut.","aide":"Cherche la valeur très éloignée des autres.","type":"zone","document":"salaires","multiple":false},{"enonce":"Calcule la moyenne des huit salaires.","aide":"Additionne les huit salaires puis divise par 8.","type":"nombre","unite":"€"},{"enonce":"Quel est le salaire médian ?","aide":"Il y a 8 valeurs : fais la moyenne de la 4e et de la 5e.","type":"nombre","unite":"€"},{"enonce":"Quelle est la moyenne des salaires des sept employés, direction exclue ?","aide":"Additionne les sept premiers salaires : 11 550 €.","type":"nombre","unite":"€"},{"enonce":"Pour décrire ce que gagne un employé « typique » de cette entreprise, quel indicateur est le plus adapté ?","aide":"Quel indicateur ne bouge pas quand un seul salaire devient énorme ?","type":"choix","options":[{"id":"a","texte":"L’étendue, car elle mesure l’écart des salaires"},{"id":"b","texte":"La moyenne, car elle utilise toutes les valeurs"},{"id":"c","texte":"La médiane, qui ignore les valeurs extrêmes"},{"id":"d","texte":"Le maximum, car il montre ce qui est possible"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k7"]},"explication":"Le salaire de la direction (**9 450 €**) est bien au-dessus des sept autres : il fait monter la moyenne."},{"cle":{"type":"nombre","valeur":2625,"tolerance":0},"affichage":"2625 €","explication":"La somme vaut 21 000 € et 21 000 ÷ 8 = **2 625 €**."},{"cle":{"type":"nombre","valeur":1675,"tolerance":0},"affichage":"1675 €","explication":"Série rangée de 8 valeurs : la médiane est la moyenne des 4e et 5e, (1 650 + 1 700) ÷ 2 = **1 675 €**."},{"cle":{"type":"nombre","valeur":1650,"tolerance":0},"affichage":"1650 €","explication":"11 550 ÷ 7 = **1 650 €** : bien plus proche de la médiane que la moyenne de 2 625 €."},{"cle":{"type":"choix","ids":["c"]},"explication":"Sept salariés sur huit gagnent moins que la moyenne. **La médiane** (1 675 €) résume mieux la situation car elle n’est pas sensible aux valeurs extrêmes."}]$ex$::jsonb),
  ('d6f0ce64-ca85-5f51-9cd2-7fecd9d86b4b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Deux classes, une même moyenne","competence":"argumenter","situation":"Le professeur de maths a corrigé le même devoir dans deux classes de 8 élèves de l’option. Il constate que les deux classes ont la même moyenne et la même médiane, et se demande si elles se ressemblent vraiment.","documents":[{"id":"notes","type":"tableau","titre":"Les notes sur 20, rangées dans l’ordre croissant","colonnes":["Rang","Classe A","Classe B"],"lignes":[[1,9,3],[2,10,5],[3,11,8],[4,11,10],[5,12,13],[6,12,15],[7,13,18],[8,14,20]],"enteteLignes":true,"source":"Notes imaginées pour l’exercice"},{"id":"resume","type":"tableau","titre":"Résumé à cinq nombres (en cours de remplissage)","colonnes":["Classe","Min","Q1","Médiane","Q3","Max"],"lignes":[["A",9,10,11.5,12,14],["B",3,"?",11.5,"?",20]],"enteteLignes":true}],"questions":[{"enonce":"Quelle est la moyenne des notes de la classe B ?","aide":"La somme des notes de B vaut 92.","type":"nombre"},{"enonce":"Quel est le premier quartile Q1 de la classe B ?","aide":"Calcule 8 ÷ 4 = 2 : prends la valeur de rang 2.","type":"nombre"},{"enonce":"Quel est le troisième quartile Q3 de la classe B ?","aide":"Calcule 3 × 8 ÷ 4 = 6 : prends la valeur de rang 6.","type":"nombre"},{"enonce":"Quel est l’écart interquartile de la classe B ?","aide":"Écart interquartile = Q3 − Q1. Compare avec la classe A : 12 − 10 = 2.","type":"nombre"},{"enonce":"Que peut-on dire des deux classes ?","aide":"Compare l’étendue et l’écart interquartile des deux classes.","type":"choix","options":[{"id":"a","texte":"La classe B a de meilleurs résultats, car son maximum est plus grand"},{"id":"b","texte":"Les deux classes ont exactement le même niveau et la même dispersion"},{"id":"c","texte":"Même moyenne et même médiane, mais la classe B est bien plus dispersée"},{"id":"d","texte":"La classe A est plus dispersée, car sa médiane est plus faible"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":11.5,"tolerance":0},"affichage":"11,5","explication":"92 ÷ 8 = **11,5**. C’est aussi la moyenne de la classe A : les moyennes ne distinguent pas les deux classes."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5","explication":"n ÷ 4 = 8 ÷ 4 = 2, entier : Q1 est la **2e valeur**, soit 5."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15","explication":"3n ÷ 4 = 6 : Q3 est la **6e valeur**, soit 15."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10","explication":"Q3 − Q1 = 15 − 5 = **10**, contre 2 pour la classe A."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les moyennes et médianes sont égales, mais l’écart interquartile (10 contre 2) et l’étendue (17 contre 5) montrent que **la classe B est beaucoup plus dispersée**. Deux séries de même moyenne peuvent être très différentes."}]$ex$::jsonb),
  ('32e56704-95df-5107-b4a8-0293761dfcbc'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le sac de billes de Nina","competence":"lire-tableau","situation":"Nina range ses billes dans un sac opaque. Elle en tire une au hasard, toutes les billes ayant la même chance d’être choisies. Le tableau donne le contenu du sac.","documents":[{"id":"sac","type":"tableau","titre":"Contenu du sac","colonnes":["Couleur","Rouge","Bleue","Verte","Jaune","Total"],"lignes":[["Nombre de billes",8,5,4,3,20]],"enteteLignes":true}],"questions":[{"enonce":"Touche le nombre total d’issues possibles.","aide":"Cherche le nombre de billes du sac en tout.","type":"zone","document":"sac","multiple":false},{"enonce":"Quelle est la probabilité de tirer une bille rouge ?","aide":"Nombre d’issues favorables ÷ nombre d’issues possibles.","type":"nombre"},{"enonce":"Quelle est la probabilité de ne pas tirer une bille bleue ?","aide":"Passe par l’événement contraire : 1 − P(bleue).","type":"nombre"},{"enonce":"Quelle est la probabilité de tirer une bille rouge ou une bille verte ?","aide":"Rouge et verte sont incompatibles : additionne les effectifs.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c5"]},"explication":"Le sac contient **20 billes** : l’univers a 20 issues équiprobables."},{"cle":{"type":"nombre","valeur":0.4,"tolerance":0},"affichage":"0,4","explication":"P(rouge) = 8 ÷ 20 = **0,4**."},{"cle":{"type":"nombre","valeur":0.75,"tolerance":0},"affichage":"0,75","explication":"P(bleue) = 5 ÷ 20 = 0,25, donc P(non bleue) = 1 − 0,25 = **0,75**."},{"cle":{"type":"nombre","valeur":0.6,"tolerance":0},"affichage":"0,6","explication":"(8 + 4) ÷ 20 = 12 ÷ 20 = **0,6**. Une bille ne peut pas être rouge et verte à la fois : on additionne."}]$ex$::jsonb),
  ('32e56704-95df-5107-b4a8-0293761dfcbc'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le jeu des deux dés de la fête du village","competence":"raisonner","situation":"À la fête du village, on lance deux dés équilibrés à six faces et on additionne les deux résultats. Pour étudier le jeu, Samuel a dressé le tableau à double entrée de toutes les sommes possibles.","documents":[{"id":"des","type":"tableau","titre":"Somme des deux dés","colonnes":["Dé 1 \\ Dé 2","1","2","3","4","5","6"],"lignes":[["1",2,3,4,5,6,7],["2",3,4,5,6,7,8],["3",4,5,6,7,8,9],["4",5,6,7,8,9,10],["5",6,7,8,9,10,11],["6",7,8,9,10,11,12]],"enteteLignes":true}],"questions":[{"enonce":"Touche toutes les cases où la somme vaut 9.","aide":"Cherche les couples dont la somme est 9 : (3 ; 6), (4 ; 5)…","type":"zone","document":"des","multiple":true},{"enonce":"Quelle est la probabilité d’obtenir une somme égale à 9 ? (Écris une fraction ou une valeur approchée à 0,01 près.)","aide":"Les 36 cases du tableau sont équiprobables.","type":"nombre"},{"enonce":"Quelle est la probabilité d’obtenir une somme supérieure ou égale à 10 ? (Fraction ou valeur approchée à 0,01 près.)","aide":"Compte les cases où la somme vaut 10, 11 ou 12, puis divise par 36.","type":"nombre"},{"enonce":"Quelle somme est la plus probable ?","aide":"Cherche la valeur qui revient le plus souvent dans le tableau (elle forme une diagonale).","type":"nombre"},{"enonce":"Quelle est la probabilité de ne pas obtenir 7 ? (Fraction ou valeur approchée à 0,01 près.)","aide":"Utilise l’événement contraire : 1 − P(somme = 7).","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c6","r3c5","r4c4","r5c3"]},"explication":"La somme vaut 9 pour (3 ; 6), (4 ; 5), (5 ; 4) et (6 ; 3) : **4 cases** sur 36."},{"cle":{"type":"nombre","valeur":0.1111111111111111,"tolerance":0.006},"affichage":"0,1111","explication":"P(somme = 9) = 4 ÷ 36 = **1/9** ≈ 0,11."},{"cle":{"type":"nombre","valeur":0.16666666666666666,"tolerance":0.006},"affichage":"0,1667","explication":"Il y a 3 cases pour 10, 2 pour 11 et 1 pour 12, soit 6 cases : 6 ÷ 36 = **1/6** ≈ 0,17."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7","explication":"La somme **7** apparaît 6 fois sur 36 : c’est la plus fréquente, devant 6 et 8 qui apparaissent 5 fois."},{"cle":{"type":"nombre","valeur":0.8333333333333334,"tolerance":0.006},"affichage":"0,8333","explication":"P(somme = 7) = 6 ÷ 36 = 1/6, donc P(somme ≠ 7) = 1 − 1/6 = **5/6** ≈ 0,83."}]$ex$::jsonb),
  ('32e56704-95df-5107-b4a8-0293761dfcbc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Deux boules tirées sans remise","competence":"modeliser","situation":"Une urne contient 3 boules rouges (R) et 2 boules bleues (B), indiscernables au toucher. Léa tire une première boule, la garde, puis tire une seconde boule. L’arbre pondéré résume l’expérience.","documents":[{"id":"arbre","type":"schema","titre":"Arbre pondéré du double tirage","largeur":340,"hauteur":260,"elements":[{"forme":"cercle","cx":24,"cy":130,"r":5,"teinte":"encre","motif":"plein"},{"forme":"ligne","de":[24,130],"a":[116,73]},{"forme":"ligne","de":[24,130],"a":[116,187]},{"forme":"cercle","cx":130,"cy":65,"r":16,"teinte":"corail","motif":"clair","texte":"R"},{"forme":"cercle","cx":130,"cy":195,"r":16,"teinte":"bleu","motif":"clair","texte":"B"},{"forme":"ligne","de":[146,63],"a":[240,30]},{"forme":"ligne","de":[146,67],"a":[240,100]},{"forme":"ligne","de":[146,193],"a":[240,160]},{"forme":"ligne","de":[146,197],"a":[240,230]},{"forme":"texte","x":58,"y":92,"texte":"3/5","ancre":"milieu"},{"forme":"texte","x":58,"y":176,"texte":"2/5","ancre":"milieu"},{"forme":"texte","x":190,"y":36,"texte":"1/2","ancre":"milieu"},{"forme":"texte","x":190,"y":108,"texte":"1/2","ancre":"milieu"},{"forme":"texte","x":190,"y":162,"texte":"3/4","ancre":"milieu"},{"forme":"texte","x":190,"y":238,"texte":"1/4","ancre":"milieu"},{"forme":"rect","x":240,"y":16,"l":46,"h":28,"arrondi":6,"teinte":"gris","motif":"clair","texte":"RR","id":"z1","zone":true},{"forme":"rect","x":240,"y":86,"l":46,"h":28,"arrondi":6,"teinte":"gris","motif":"clair","texte":"RB","id":"z2","zone":true},{"forme":"rect","x":240,"y":146,"l":46,"h":28,"arrondi":6,"teinte":"gris","motif":"clair","texte":"BR","id":"z3","zone":true},{"forme":"rect","x":240,"y":216,"l":46,"h":28,"arrondi":6,"teinte":"gris","motif":"clair","texte":"BB","id":"z4","zone":true}]},{"id":"evts","type":"tableau","titre":"Deux événements à étudier","colonnes":["Événement","Se réalise quand…"],"lignes":[["A","la 1re boule est rouge"],["B","la 2e boule est rouge"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’issue « la 1re boule est bleue, puis la 2e est rouge ».","aide":"Suis la branche B depuis la racine, puis la branche R.","type":"zone","document":"arbre","multiple":false},{"enonce":"Quelle est la probabilité de l’événement B : « la 2e boule est rouge » ?","aide":"Additionne les chemins qui finissent par R : RR et BR.","type":"nombre"},{"enonce":"Quelle est la probabilité de A ∩ B : « les deux boules sont rouges » ?","aide":"Un seul chemin : multiplie 3/5 par 1/2.","type":"nombre"},{"enonce":"Quelle est la probabilité de A ∪ B : « au moins une des deux boules est rouge » ?","aide":"Utilise P(A ∪ B) = P(A) + P(B) − P(A ∩ B) avec P(A) = 3/5.","type":"nombre"},{"enonce":"Quelle est la probabilité qu’aucune des deux boules ne soit rouge ?","aide":"Un seul chemin convient : B puis B.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"On suit la branche B puis la branche R : c’est l’issue **BR**, de probabilité 2/5 × 3/4 = 0,3."},{"cle":{"type":"nombre","valeur":0.6,"tolerance":0},"affichage":"0,6","explication":"On multiplie le long de chaque chemin puis on additionne : P(RR) + P(BR) = 0,3 + 0,3 = **0,6**."},{"cle":{"type":"nombre","valeur":0.3,"tolerance":0},"affichage":"0,3","explication":"P(A ∩ B) = P(RR) = 3/5 × 1/2 = **0,3**."},{"cle":{"type":"nombre","valeur":0.9,"tolerance":0},"affichage":"0,9","explication":"P(A ∪ B) = 0,6 + 0,6 − 0,3 = **0,9**. On retranche l’intersection pour ne pas la compter deux fois."},{"cle":{"type":"nombre","valeur":0.1,"tolerance":0},"affichage":"0,1","explication":"P(BB) = 2/5 × 1/4 = **0,1**. C’est aussi 1 − 0,9 : l’événement contraire de A ∪ B."}]$ex$::jsonb),
  ('9a7eedff-74a9-5095-87f1-a7ecb7ce6d4b'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La pièce de Mina est-elle truquée ?","competence":"raisonner","situation":"Mina lance 100 fois une pièce de monnaie et obtient 56 fois pile. Si la pièce est équilibrée, la probabilité d’obtenir pile est p = 0,5. Mina veut savoir si son résultat est étonnant.","documents":[{"id":"releve","type":"tableau","titre":"Le relevé de Mina","colonnes":["Nombre de lancers","Nombre de piles","Fréquence f"],"lignes":[[100,56,"?"]]},{"id":"axe","type":"droite","titre":"Fréquences possibles","min":0.3,"max":0.7,"pas":0.1,"division":10,"points":[{"id":"z1","valeur":0.56,"nom":"f"}],"graduationsCliquables":true}],"questions":[{"enonce":"Quelle est la fréquence observée f de pile ?","aide":"Divise le nombre de piles par le nombre de lancers.","type":"nombre"},{"enonce":"Pour n = 100, quelle est la demi-largeur 1/√n de l’intervalle de fluctuation ?","aide":"Calcule √100, puis l’inverse.","type":"nombre"},{"enonce":"Touche les deux bornes de l’intervalle de fluctuation [p − 1/√n ; p + 1/√n] pour p = 0,5.","aide":"Les bornes sont à 0,1 de chaque côté de p = 0,5.","type":"zone","document":"axe","multiple":true},{"enonce":"La fréquence observée 0,56 est dans l’intervalle. Que conclut-on ?","aide":"Une fréquence dans l’intervalle ne contredit pas l’hypothèse, elle ne la démontre pas non plus.","type":"choix","options":[{"id":"a","texte":"On ne rejette pas l’hypothèse d’une pièce équilibrée"},{"id":"b","texte":"On prouve que la pièce est équilibrée"},{"id":"c","texte":"On prouve que la pièce est truquée"},{"id":"d","texte":"On rejette l’hypothèse d’une pièce équilibrée"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.56,"tolerance":0},"affichage":"0,56","explication":"f = 56 ÷ 100 = **0,56**."},{"cle":{"type":"nombre","valeur":0.1,"tolerance":0},"affichage":"0,1","explication":"√100 = 10, donc 1/√100 = **0,1**."},{"cle":{"type":"zone","ids":["v0.4","v0.6"]},"explication":"L’intervalle est [0,5 − 0,1 ; 0,5 + 0,1] = **[0,4 ; 0,6]**. Les bornes sont les graduations 0,4 et 0,6."},{"cle":{"type":"choix","ids":["a"]},"explication":"Comme 0,56 appartient à [0,4 ; 0,6], on **ne rejette pas** l’hypothèse — ce qui ne démontre pas que la pièce est équilibrée."}]$ex$::jsonb),
  ('9a7eedff-74a9-5095-87f1-a7ecb7ce6d4b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les cartes rares des boîtes de céréales","competence":"raisonner","situation":"Un fabricant affirme que 25 % des boîtes de céréales contiennent une carte rare (p = 0,25). Trois associations de consommateurs vérifient : chacune ouvre un certain nombre de boîtes et compte les cartes rares.","documents":[{"id":"assos","type":"tableau","titre":"Les relevés des trois associations","colonnes":["Association","Boîtes ouvertes","Cartes rares","Fréquence f"],"lignes":[["A",400,130,"?"],["B",100,31,0.31],["C",1600,450,0.28125]],"enteteLignes":true,"source":"Relevés imaginés pour l’exercice"}],"questions":[{"enonce":"Quelle est la fréquence observée de cartes rares pour l’association A ?","aide":"Divise 130 par 400.","type":"nombre"},{"enonce":"Quelle est la demi-largeur 1/√n de l’intervalle de fluctuation pour l’association C ?","aide":"n = 1 600 : √1 600 = 40.","type":"nombre"},{"enonce":"Touche les associations dont la fréquence observée sort de l’intervalle de fluctuation au seuil de 95 %.","aide":"Calcule [0,25 − 1/√n ; 0,25 + 1/√n] pour chaque association puis compare à f.","type":"zone","document":"assos","multiple":true},{"enonce":"Que peut conclure l’association B, qui a trouvé 31 cartes rares sur 100 boîtes ?","aide":"Compare f = 0,31 à l’intervalle [0,15 ; 0,35].","type":"choix","options":[{"id":"a","texte":"Elle ne rejette pas l’affirmation du fabricant"},{"id":"b","texte":"Elle prouve que le fabricant a menti"},{"id":"c","texte":"Elle rejette l’affirmation du fabricant"},{"id":"d","texte":"Elle prouve que l’affirmation du fabricant est vraie"}],"multiple":false}]}$ex$::jsonb,
