  ('9a7eedff-74a9-5095-87f1-a7ecb7ce6d4b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Quelle taille pour un sondage fiable ?","competence":"modeliser","situation":"Une radio veut estimer la proportion p de lycéens qui utilisent leur téléphone en cours. Elle se demande combien de personnes interroger. Un technicien a tracé la demi-largeur 1/√n de l’intervalle de fluctuation selon la taille n, et écrit un petit programme Python.","documents":[{"id":"largeur","type":"graphique","forme":"barres","titre":"Demi-largeur 1/√n selon la taille n de l’échantillon","categories":["100","400","1 600","6 400"],"series":[{"nom":"Demi-largeur 1/√n","valeurs":[0.1,0.05,0.025,0.0125],"teinte":"ambre"}],"axeY":{"min":0,"max":0.1,"pas":0.025},"axeX":{"titre":"Taille n"}},{"id":"prog","type":"texte","genre":"consigne","titre":"Le programme du technicien","auteur":"Programme écrit pour l’exercice","blocs":["from math import sqrt","n = 2500","print(1 / sqrt(n))"]}],"questions":[{"enonce":"Touche la barre dont la hauteur est la moitié de celle de la barre n = 400.","aide":"Il faut multiplier n par 4 pour diviser la demi-largeur par 2.","type":"zone","document":"largeur","multiple":false},{"enonce":"Qu’affiche ce programme ?","aide":"Calcule 1 ÷ √2 500, avec √2 500 = 50.","type":"nombre"},{"enonce":"Pour p = 0,5 et n = 2 500, quelle est la borne supérieure de l’intervalle de fluctuation ?","aide":"Borne supérieure = p + 1/√n, et 1/√n est la valeur affichée par le programme.","type":"nombre"},{"enonce":"Quelle taille minimale n faut-il pour que la demi-largeur 1/√n soit inférieure ou égale à 0,01 ?","aide":"1/√n ≤ 0,01 revient à √n ≥ 100.","type":"nombre"},{"enonce":"La radio sonde 10 000 de ses auditeurs, recrutés sur son compte de réseau social, pour connaître l’opinion de tous les lycéens. Est-ce fiable ?","aide":"Les auditeurs de la radio ressemblent-ils à l’ensemble des lycéens ?","type":"choix","options":[{"id":"a","texte":"Non : il faudrait au moins 100 000 personnes"},{"id":"b","texte":"Oui : la demi-largeur n’est que de 0,01"},{"id":"c","texte":"Non : échantillon biaisé, sa taille n’y change rien"},{"id":"d","texte":"Oui : 10 000 personnes suffisent toujours"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"La barre n = 1 600 vaut 0,025, soit la moitié de 0,05 : multiplier la taille par **4** divise l’incertitude par 2."},{"cle":{"type":"nombre","valeur":0.02,"tolerance":0},"affichage":"0,02","explication":"√2 500 = 50 et 1 ÷ 50 = **0,02** : c’est la demi-largeur pour n = 2 500."},{"cle":{"type":"nombre","valeur":0.52,"tolerance":0},"affichage":"0,52","explication":"0,5 + 0,02 = **0,52**. L’intervalle est [0,48 ; 0,52]."},{"cle":{"type":"nombre","valeur":10000,"tolerance":0},"affichage":"10 000","explication":"√n ≥ 100 donne n ≥ 100² = **10 000** personnes : pour passer de 0,1 à 0,01, il faut multiplier n par 100."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un mauvais recrutement donne un échantillon **biaisé**, et un biais ne se corrige pas par la taille. L’intervalle de fluctuation suppose un tirage aléatoire dans toute la population."}]$ex$::jsonb),
  ('32257dd2-f18f-51b8-b4da-e741eace3198'::uuid, 1, 1, 5, 20, 3,
