  ('32257dd2-f18f-51b8-b4da-e741eace3198'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le moment où tout change","competence":"analyser-document","situation":"Au concours d’analyse, Sofia écoute « Lever de lune », une pièce imaginée pour l’exercice. Elle a noté l’intensité (de 1, très doux, à 5, très fort) puis rempli un journal d’écoute. Elle cherche le moment qui révèle l’intention du compositeur.","documents":[{"id":"inten","type":"graphique","forme":"courbe","titre":"Intensité au fil de la pièce","categories":["0:00","0:45","1:30","2:10","2:40"],"series":[{"nom":"Intensité","valeurs":[1,2,3,5,4],"teinte":"violet"}],"axeY":{"titre":"Intensité (1 = très doux, 5 = très fort)","min":0,"max":5,"pas":1},"axeX":{"titre":"Moment de la pièce"},"valeurs":false,"source":"Pièce imaginée pour l’exercice"},{"id":"journal","type":"tableau","titre":"Le journal d’écoute de Sofia","colonnes":["Moment","Texture","Mode","Cadence"],"lignes":[["0:00","Monodie : flûte seule","Mineur","Phrase ouverte"],["0:45","Homophonie : flûte et cordes","Mineur","Suspensive"],["1:30","Homophonie","Mineur","Parfaite"],["2:10","Polyphonie : trois lignes","Majeur","Rompue"],["2:40","Homophonie","Majeur","Parfaite"]],"enteteLignes":true}],"questions":[{"enonce":"Touche **le moment où l’intensité fait le plus grand bond** par rapport au précédent.","aide":"Compare l’écart entre deux points voisins : cherche le plus grand saut.","type":"zone","document":"inten","multiple":false},{"enonce":"Touche **le moment où la texture et le mode changent en même temps**.","aide":"Lis les colonnes « Texture » et « Mode » : cherche la ligne où les deux changent.","type":"zone","document":"journal","multiple":false},{"enonce":"Pourquoi le moment de 2:10 est-il le plus révélateur pour l’analyse ?","aide":"Le cours dit que l’intention se lit au moment de la rupture.","type":"choix","options":[{"id":"a","texte":"C’est le moment le plus long de toute la pièce entendue"},{"id":"b","texte":"C’est là que l’intensité est la plus faible de la pièce"},{"id":"c","texte":"C’est le seul moment où l’on entend la flûte jouer seule"},{"id":"d","texte":"Un changement de texture ou de mode est un geste du compositeur"}],"multiple":false},{"enonce":"Combien de secondes séparent l’entrée des cordes (0:45) de la rupture (2:10) ?","aide":"Passe tout en secondes : 2:10 = 130 s, 0:45 = 45 s.","type":"nombre","unite":"secondes"},{"enonce":"Relie chaque cadence du journal à son effet.","aide":"Reprends les trois cadences notées par Sofia dans la colonne de droite.","type":"association","gauche":[{"id":"g0","texte":"Parfaite"},{"id":"g1","texte":"Suspensive"},{"id":"g2","texte":"Rompue"}],"droite":[{"id":"d0","texte":"Surprise : l’attente est déjouée"},{"id":"d1","texte":"Achèvement : la phrase se ferme"},{"id":"d2","texte":"Attente : la phrase reste ouverte"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"Entre 1:30 (intensité 3) et 2:10 (intensité 5), l’intensité gagne **2 niveaux**, le plus grand bond du graphique."},{"cle":{"type":"zone","ids":["r3c0"]},"explication":"À **2:10**, on passe de l’homophonie à la polyphonie et du mineur au majeur : une vraie rupture."},{"cle":{"type":"choix","ids":["d"]},"explication":"C’est au moment de la **rupture** que l’intention se lit le mieux : un changement de texture ou de mode est **toujours un geste, jamais un hasard**."},{"cle":{"type":"nombre","valeur":85,"tolerance":0},"affichage":"85 secondes","explication":"2 min 10 s = 130 s et 0 min 45 s = 45 s : 130 − 45 = **85 secondes**."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"**Parfaite** : achèvement ; **suspensive** : attente ; **rompue** : surprise. À 2:10, la cadence rompue renforce la rupture."}]$ex$::jsonb),
  ('759acb4f-463d-50c8-8e6c-5dd7294c7c2d'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un siècle d’outils sonores","competence":"se-reperer-temps","situation":"Pour son exposé, Maël place sur une frise quelques dates de la musique enregistrée et électronique, pour voir comment les outils ont changé la façon de composer.","documents":[{"id":"frise","type":"frise","titre":"Des outils qui changent la musique","debut":1900,"fin":2000,"pas":10,"periodes":[{"id":"z1","debut":1900,"fin":1909,"nom":"Années 1900","teinte":"ambre"},{"id":"z2","debut":1950,"fin":1959,"nom":"Années 1950","teinte":"turquoise"}],"evenements":[{"id":"z3","date":1948,"nom":"Musique concrète"},{"id":"z4","date":1983,"nom":"Norme MIDI"}],"source":"Repères de cours"}],"questions":[{"enonce":"Le multipiste fait du studio un instrument. Touche **la période** de son apparition.","aide":"Le cours situe le multipiste dans les années 1950.","type":"zone","document":"frise","multiple":false},{"enonce":"Touche **l’événement qui permet aux machines de dialoguer entre elles**.","aide":"Pense à la norme qui transporte des instructions, et non du son.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la musique concrète de Schaeffer de la norme MIDI ?","aide":"Lis les deux dates sur la frise, puis soustrais.","type":"nombre","unite":"ans"},{"enonce":"Relie chaque outil à ce qu’il change.","aide":"La musique concrète utilise des bruits réels : une porte, un train.","type":"association","gauche":[{"id":"g0","texte":"Microphone et disque"},{"id":"g1","texte":"Musique concrète"},{"id":"g2","texte":"Multipiste"},{"id":"g3","texte":"MIDI"}],"droite":[{"id":"d0","texte":"Le studio devient un instrument"},{"id":"d1","texte":"Le son enregistré du réel devient matériau"},{"id":"d2","texte":"Les machines dialoguent entre elles"},{"id":"d3","texte":"L’œuvre devient un objet qu’on possède"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le **multipiste** apparaît dans les **années 1950** : le studio devient un instrument."},{"cle":{"type":"zone","ids":["z4"]},"explication":"La **norme MIDI** (1983) permet aux machines de dialoguer entre elles."},{"cle":{"type":"nombre","valeur":35,"tolerance":0},"affichage":"35 ans","explication":"1983 − 1948 = **35 ans**."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"**Microphone et disque** : l’œuvre devient un objet ; **musique concrète** : le son du réel devient matériau ; **multipiste** : le studio devient un instrument ; **MIDI** : les machines dialoguent."}]$ex$::jsonb),
  ('759acb4f-463d-50c8-8e6c-5dd7294c7c2d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le même fichier, deux sons","competence":"comprendre-langue","situation":"Hugo a deux fichiers du même morceau. Il les envoie sur deux synthétiseurs et s’étonne : le même fichier ne sonne pas pareil d’une machine à l’autre.","documents":[{"id":"fichiers","type":"tableau","titre":"Les deux fichiers de Hugo","colonnes":["Fichier","Ce qu’il contient","Poids"],"lignes":[["morceau.mid","Des instructions : quelle note, quelle intensité, quelle durée","20 Ko"],["morceau.wav","Le son enregistré lui-même","40 Mo"]],"enteteLignes":true,"source":"Poids arrondis, imaginés pour l’exercice"},{"id":"machines","type":"schema","titre":"Un fichier, deux machines","largeur":320,"hauteur":180,"elements":[{"forme":"rect","x":14,"y":68,"l":92,"h":40,"teinte":"violet","motif":"clair","texte":"morceau.mid"},{"forme":"ligne","de":[108,80],"a":[198,44],"fleche":"fin"},{"forme":"ligne","de":[108,96],"a":[198,134],"fleche":"fin"},{"forme":"rect","x":200,"y":20,"l":106,"h":44,"teinte":"turquoise","motif":"clair","texte":"Synthé A","id":"z1","zone":true},{"forme":"texte","x":253,"y":80,"texte":"sonne comme un piano","taille":"petit","ancre":"milieu","italique":true},{"forme":"rect","x":200,"y":112,"l":106,"h":44,"teinte":"ambre","motif":"clair","texte":"Synthé B","id":"z2","zone":true},{"forme":"texte","x":253,"y":172,"texte":"sonne comme un saxophone","taille":"petit","ancre":"milieu","italique":true}]}],"questions":[{"enonce":"Touche **le fichier qui contient le son lui-même**.","aide":"Un des deux fichiers est un enregistrement ; l’autre ne contient que des consignes.","type":"zone","document":"fichiers","multiple":false},{"enonce":"Le fichier .wav pèse combien de fois plus que le fichier .mid ? (1 Mo = 1 000 Ko)","aide":"Convertis d’abord 40 Mo en Ko, puis divise par 20 Ko.","type":"nombre","unite":"fois"},{"enonce":"Range chaque élément : le MIDI le transporte-t-il ?","aide":"Le MIDI transporte des instructions : note, intensité, durée. Jamais de son.","type":"categories","categories":[{"id":"c0","texte":"Le MIDI le transporte"},{"id":"c1","texte":"Le MIDI ne le transporte pas"}],"items":[{"id":"i0","texte":"Quelle note jouer"},{"id":"i1","texte":"Le son d’un vrai piano"},{"id":"i2","texte":"Pendant combien de temps"},{"id":"i3","texte":"Une voix enregistrée"},{"id":"i4","texte":"Avec quelle intensité"},{"id":"i5","texte":"L’écho d’une salle de concert"}]},{"enonce":"Pourquoi le synthé A et le synthé B sonnent-ils différemment avec le même fichier ?","aide":"Relis la colonne « Ce qu’il contient » pour le fichier .mid.","type":"choix","options":[{"id":"a","texte":"Le synthé B déforme volontairement toutes les notes du fichier"},{"id":"b","texte":"Le fichier contient en réalité deux enregistrements différents"},{"id":"c","texte":"Le fichier ne donne que des instructions : chaque machine fait son son"},{"id":"d","texte":"Le synthé A lit le fichier beaucoup plus vite que le synthé B"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0"]},"explication":"Le fichier **.wav** contient le son enregistré. Le fichier .mid ne contient que des instructions."},{"cle":{"type":"nombre","valeur":2000,"tolerance":0},"affichage":"2000 fois","explication":"40 Mo = 40 000 Ko ; 40 000 ÷ 20 = **2 000 fois** plus lourd. Des instructions pèsent très peu, un son enregistré beaucoup."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c0","i5":"c1"}},"explication":"Le **MIDI** transporte **quelle note, quelle intensité, quelle durée**. Il ne transporte **pas de son** : ni piano, ni voix, ni acoustique d’une salle."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un fichier MIDI ne contient **que des instructions** : chaque machine fabrique son propre son à partir de ces notes. D’où des résultats différents."}]$ex$::jsonb),
  ('759acb4f-463d-50c8-8e6c-5dd7294c7c2d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Filtrer, empiler, moduler","competence":"analyser-document","situation":"Le synthé de l’atelier musique affiche le spectre d’un son : l’intensité de chacune de ses huit premières harmoniques, avant et après un filtre. Lola doit comprendre comment ce synthé fabrique son timbre.","documents":[{"id":"spectre","type":"graphique","forme":"courbe","titre":"Spectre simplifié d’un son","categories":["1","2","3","4","5","6","7","8"],"series":[{"nom":"Son riche (avant le filtre)","valeurs":[8,7,6,5,4,3,2,1],"teinte":"violet"},{"nom":"Après le filtre","valeurs":[8,7,5,2,0,0,0,0],"teinte":"corail"}],"axeY":{"titre":"Intensité","min":0,"max":8,"pas":2},"axeX":{"titre":"Numéro de l’harmonique"},"source":"Valeurs imaginées pour l’exercice"},{"id":"notice","type":"texte","genre":"article","titre":"Notice du synthé de l’atelier","auteur":"Notice écrite pour l’exercice","blocs":["**Mode A** : on part d’un son très simple et on empile des harmoniques pour construire le timbre.","**Mode B** : on part d’un son riche en harmoniques et on filtre ce qu’on ne veut pas garder.","**Mode C** : on module la fréquence d’un oscillateur par celle d’un autre oscillateur."],"source":"Notice écrite pour l’exercice"}],"questions":[{"enonce":"Touche **la première harmonique que le filtre supprime complètement**.","aide":"Cherche le premier point de la courbe « après le filtre » qui tombe à zéro.","type":"zone","document":"spectre","multiple":false},{"enonce":"Combien d’harmoniques le filtre supprime-t-il complètement ?","aide":"Compte les points à zéro sur la courbe « après le filtre ».","type":"nombre","unite":"harmoniques"},{"enonce":"Relie chaque mode de la notice au nom de sa synthèse.","aide":"Additive : on ajoute des harmoniques. Soustractive : on retire. FM : modulation de fréquence.","type":"association","gauche":[{"id":"g0","texte":"Mode A"},{"id":"g1","texte":"Mode B"},{"id":"g2","texte":"Mode C"}],"droite":[{"id":"d0","texte":"Synthèse FM"},{"id":"d1","texte":"Synthèse soustractive"},{"id":"d2","texte":"Synthèse additive"}]},{"enonce":"Range chaque matériau sonore : musique concrète ou son entièrement synthétique ?","aide":"La musique concrète part de sons du réel enregistrés, comme chez Pierre Schaeffer en 1948.","type":"categories","categories":[{"id":"c0","texte":"Musique concrète"},{"id":"c1","texte":"Son synthétique"}],"items":[{"id":"i0","texte":"Un son filtré par le synthé de l’atelier"},{"id":"i1","texte":"Un train enregistré en gare"},{"id":"i2","texte":"Une porte qui claque, enregistrée"},{"id":"i3","texte":"Un son créé par un oscillateur seul"}]},{"enonce":"Un morceau est généré à partir d’une simple phrase tapée par un utilisateur. Quelle question cela rouvre-t-il le plus directement ?","aide":"Chaque nouvel outil déplace la frontière entre interpréter et fabriquer.","type":"choix","options":[{"id":"a","texte":"Le morceau est-il en mode majeur ?"},{"id":"b","texte":"Qui est l’auteur du morceau ?"},{"id":"c","texte":"Combien de pistes comporte l’enregistrement ?"},{"id":"d","texte":"Faut-il un microphone pour le jouer ?"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"À partir de l’**harmonique 5**, la courbe filtrée tombe à zéro : le filtre ne laisse plus rien passer."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 harmoniques","explication":"Les harmoniques **5, 6, 7 et 8** sont à zéro : le filtre en supprime **4**."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"**Mode A** : synthèse **additive** (on empile) ; **mode B** : synthèse **soustractive** (on filtre, comme sur le graphique) ; **mode C** : synthèse **FM** (on module)."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"La **musique concrète** de Schaeffer utilise des sons du réel enregistrés ; l’**électroacoustique** élargit ensuite le matériau à tout son possible, y compris entièrement synthétique."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’intelligence artificielle générative repose la question de ce qu’est un **auteur** : celui qui tape la phrase, le programme ou ceux dont il s’inspire ?"}]$ex$::jsonb),
  ('082a5ebd-0e18-5ff8-a38b-8588b0e869ba'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Deux interprètes, une partition","competence":"lire-tableau","situation":"Deux pianistes jouent le même passage d’une même partition. Camille compare leurs choix dans un tableau et en déduit ce que décide un interprète.","documents":[{"id":"comp","type":"tableau","titre":"Le même passage, deux interprétations","colonnes":["Critère","Interprète A","Interprète B"],"lignes":[["Tempo (pulsations par minute)",60,80],["Durée du passage","3 min 00 s","2 min 15 s"],["Nuances","Très douces, peu de relief","Contrastées : le thème ressort"],["Phrasé","Notes très liées","Notes plus détachées"]],"enteteLignes":true,"source":"Données imaginées pour l’exercice"}],"questions":[{"enonce":"Touche **le tempo le plus rapide**.","aide":"Plus il y a de pulsations par minute, plus la musique va vite.","type":"zone","document":"comp","multiple":false},{"enonce":"De combien de secondes la version B est-elle plus courte que la version A ?","aide":"Passe les deux durées en secondes avant de soustraire : 3 min = 180 s.","type":"nombre","unite":"secondes"},{"enonce":"Relie chaque choix de l’interprète à ce qu’il change à l’écoute.","aide":"Le tableau compare le tempo, les nuances et le phrasé : relie chaque ligne à son effet.","type":"association","gauche":[{"id":"g0","texte":"Le tempo"},{"id":"g1","texte":"Les nuances"},{"id":"g2","texte":"Le phrasé"},{"id":"g3","texte":"L’instrument"}],"droite":[{"id":"d0","texte":"L’énergie, la respiration de la phrase"},{"id":"d1","texte":"Le sens : où la phrase respire"},{"id":"d2","texte":"La couleur, l’équilibre, la puissance"},{"id":"d3","texte":"Le relief, ce qui passe au premier plan"}]}]}$ex$::jsonb,
