  ('082a5ebd-0e18-5ff8-a38b-8588b0e869ba'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Bach avec les instruments de son temps","competence":"analyser-document","situation":"Un ensemble « historiquement informé » joue le même Bach qu’un grand orchestre moderne. Clara reçoit une fiche comparant les deux versions et doit retrouver laquelle est laquelle.","documents":[{"id":"versions","type":"tableau","titre":"Deux versions d’un même concerto","colonnes":["Critère","Version A","Version B"],"lignes":[["Diapason (la)","440 Hz","415 Hz"],["Cordes","En acier","En boyau"],["Effectif","60 musiciens","22 musiciens"],["Articulation","Appuyée, continue","Plus légère"]],"enteteLignes":true,"source":"Effectifs imaginés ; diapasons usuels"}],"questions":[{"enonce":"Les musiciens « historiquement informés » jouent sur des cordes anciennes. Touche **la case qui décrit leurs cordes**.","aide":"Ils utilisent des cordes en boyau, comme à l’époque de Bach.","type":"zone","document":"versions","multiple":false},{"enonce":"De combien de hertz le diapason de la version B est-il plus bas que celui de la version A ?","aide":"Lis les deux valeurs dans la ligne « Diapason », puis soustrais.","type":"nombre","unite":"Hz"},{"enonce":"Range chaque caractéristique : orchestre moderne ou pratique d’époque ?","aide":"Reprends les colonnes A et B du tableau.","type":"categories","categories":[{"id":"c0","texte":"Orchestre moderne"},{"id":"c1","texte":"Pratique d’époque"}],"items":[{"id":"i0","texte":"Effectif réduit"},{"id":"i1","texte":"Cordes en boyau"},{"id":"i2","texte":"Cordes en acier"},{"id":"i3","texte":"Diapason à 440 Hz"},{"id":"i4","texte":"Diapason plus bas"},{"id":"i5","texte":"Articulation appuyée et continue"}]},{"enonce":"Que montre le contraste entre les deux versions ?","aide":"Le même Bach devient méconnaissable : qu’est-ce que cela prouve ?","type":"choix","options":[{"id":"a","texte":"La version A est la seule qui respecte vraiment la partition écrite"},{"id":"b","texte":"Les deux versions sonnent de façon identique à l’oreille"},{"id":"c","texte":"La version B est erronée à cause de son diapason plus bas que A"},{"id":"d","texte":"Une partition s’entend très différemment : aucune version n’est LA fidèle"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"La **version B** joue sur des cordes en **boyau** : c’est la version historiquement informée. La version A, en acier, est celle de l’orchestre moderne."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 Hz","explication":"440 − 415 = **25 Hz** : le diapason ancien est plus bas qu’aujourd’hui."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c1","i5":"c0"}},"explication":"La musique **historiquement informée** rejoue le répertoire avec les moyens de l’époque : **diapason plus bas, cordes en boyau, effectifs réduits, articulation plus légère**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le même Bach devient méconnaissable : cela montre que **« la » version fidèle n’existe pas**. Chaque interprétation est un choix."}]$ex$::jsonb),
