   $ex${"titre":"La limonade de Théo","competence":"calculer","situation":"Théo prépare de la limonade maison pour le goûter : il dissout du sucre dans de l’eau puis complète jusqu’au trait de sa carafe graduée.","documents":[{"id":"recette","type":"fiche","modele":"recette","entete":"Limonade de Théo","sousTitre":"Pour toute la bande","emoji":"🍋","lignes":[{"texte":"Sucre en poudre","valeur":"15 g","id":"z1"},{"texte":"Eau","valeur":"jusqu’au trait de la carafe","id":"z2"},{"separateur":true},{"texte":"Volume de limonade obtenu","valeur":"0,50 L","id":"z3","gras":true}],"pied":"Recette écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui désigne le soluté de cette solution.","aide":"Le soluté est l’espèce dissoute, présente en petite quantité.","type":"zone","document":"recette","multiple":false},{"enonce":"Calcule la concentration en masse de sucre dans la limonade, en g·L⁻¹.","aide":"Divise la masse de sucre par le volume de la solution obtenue.","type":"nombre","unite":"g·L⁻¹"},{"enonce":"Théo se sert un verre de 0,20 L. Quelle masse de sucre ce verre contient-il ?","aide":"Utilise t = m / V pour retrouver m, avec la concentration trouvée juste avant.","type":"nombre","unite":"g"},{"enonce":"Pourquoi Théo complète-t-il jusqu’au trait de la carafe plutôt que de verser 0,50 L d’eau ?","aide":"Relis la précision sur V dans la définition de la concentration en masse.","type":"choix","options":[{"id":"a","texte":"Le trait de la carafe donne directement la masse de sucre dissous"},{"id":"b","texte":"Il faut toujours plus d’eau que de sucre pour que la solution soit saturée"},{"id":"c","texte":"Le sucre disparaît entièrement et n’occupe aucune place dans la solution"},{"id":"d","texte":"Le volume qui compte est celui de la solution obtenue, pas celui de l’eau ajoutée"}],"multiple":false}]}$ex$::jsonb,
