  ('4ac624e9-b754-5dfd-a02f-d91fe2b9af1d'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Compléter des équations de désintégration","competence":"raisonner","situation":"En TP, Rémi doit compléter trois équations de désintégration à l’aide des lois de Soddy : la conservation du nombre de nucléons A et du nombre de charge Z.","documents":[{"id":"equations","type":"tableau","titre":"Trois désintégrations","colonnes":["Type","Équation"],"enteteLignes":true,"lignes":[["α","²³⁸₉₂U → X + ⁴₂He"],["β⁻","¹⁴₆C → Y + ⁰₋₁e"],["β⁺","²²₁₁Na → W + ⁰₊₁e"]],"source":"Équations proposées pour l’exercice"},{"id":"elements","type":"tableau","titre":"Quelques éléments","colonnes":["Z","Symbole"],"enteteLignes":true,"lignes":[["7","N"],["10","Ne"],["12","Mg"],["90","Th"],["91","Pa"]]}],"questions":[{"enonce":"Quel est le nombre de masse A du noyau X ?","aide":"Conservation de A : 238 = A(X) + 4.","type":"nombre"},{"enonce":"Quel est le nombre de charge Z du noyau X ?","aide":"Conservation de Z : 92 = Z(X) + 2.","type":"nombre"},{"enonce":"Touche le symbole de l’élément Y formé par la désintégration β⁻ du carbone 14.","aide":"Z se conserve : 6 = Z(Y) + (−1).","type":"zone","document":"elements","multiple":false},{"enonce":"Quel est le nombre de charge Z du noyau W formé par la désintégration β⁺ du sodium 22 ?","aide":"Conservation de Z : 11 = Z(W) + 1.","type":"nombre"},{"enonce":"Associe chaque désintégration à son effet sur Z.","aide":"Reviens aux trois équations du tableau.","type":"association","gauche":[{"id":"g0","texte":"Désintégration alpha"},{"id":"g1","texte":"Désintégration bêta moins"},{"id":"g2","texte":"Désintégration bêta plus"}],"droite":[{"id":"d0","texte":"Z augmente de 1"},{"id":"d1","texte":"Z diminue de 1"},{"id":"d2","texte":"Z diminue de 2"}]}]}$ex$::jsonb,
